 catalog['fixtures'].append({'id':'implicit_rational_section_'+suffix,'target':'polynomial_rational_sections','test':test,'owner':'Hypercurve polynomial/rational section dispatch, monotone common-component correspondences and shared source-chart conversion','properties':['P15','P17','P18','P19','P20'],'domain':domain,'origins':['authored','selected_implicit','generated'],'families':['ImplicitPolynomial','QuadraticBezier','CubicBezier','RationalBezier','RationalQuadraticBezier','CircularArc','PolynomialBSpline','Nurbs'],'policies':['STRICT','APPROXIMATE_512'] if suffix in ('retry','selected_trim') else ['STRICT'],'semantics':'Homogeneous substitution proposes rational source parameters; the original polynomial branch selects its fiber. Common supports retain monotone local source charts, exact inverse correspondence and closed endpoint semantics. These are named algebraic fixtures, not complete general coefficients, collapsed traces, arbitrary image maps, normal parallels, filled-region or native archive closure. In-memory point replay is separate from fresh-process native replay. Counted work and external fixture timeouts do not bound all arithmetic or memory.','claims':claims,'oracle':oracle,'timeout_seconds':300})
